package com.arcvision.arcledger.ui.main; import android.os.Bundle; import androidx.appcompat.app.*; import androidx.fragment.app.Fragment; import com.arcvision.arcledger.R; import com.arcvision.arcledger.ui.customers.CustomersFragment; import com.arcvision.arcledger.ui.dashboard.DashboardFragment; import com.arcvision.arcledger.ui.reports.ReportsFragment; import com.arcvision.arcledger.ui.settings.SettingsFragment; import com.arcvision.arcledger.ui.transactions.TransactionsFragment; import com.google.android.material.bottomnavigation.BottomNavigationView;
public class MainActivity extends AppCompatActivity { @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);BottomNavigationView nav=findViewById(R.id.bottomNav);nav.setOnItemSelectedListener(i->{Fragment f;int id=i.getItemId();if(id==R.id.menu_transactions)f=new TransactionsFragment();else if(id==R.id.menu_reports)f=new ReportsFragment();else if(id==R.id.menu_customers)f=new CustomersFragment();else if(id==R.id.menu_settings)f=new SettingsFragment();else f=new DashboardFragment();getSupportFragmentManager().beginTransaction().replace(R.id.fragmentContainer,f).commit();return true;});nav.setSelectedItemId(R.id.menu_dashboard);} }
